const tabs:{key:Key;label:string;description:string;icon:any}[]=[
 {key:'programs',label:'Examination Programs',description:'Set up examination sessions, classes, subjects, marks and responsible staff.',icon:BookOpenCheck},
 {key:'timetable',label:'Examination Timetable',description:'Coordinate examination dates, subjects, rooms, invigilators and schedules.',icon:CalendarClock},
 {key:'questions',label:'Question Bank',description:'Create reusable objective and descriptive questions by subject, topic and difficulty.',icon:FileQuestion},
 {key:'online',label:'Online Tests & Quizzes',description:'Build timed tests, randomise questions and manage student submissions.',icon:Timer},
 {key:'marks',label:'Marks Entry',description:'Record marks, absences and remarks, validate limits and save drafts.',icon:ClipboardCheck},
 {key:'grading',label:'Grades & Grading System',description:'Configure grade scales, passing thresholds and assessment weights.',icon:Award},
 {key:'results',label:'Results & Result Approval',description:'Review, verify, approve and publish examination results.',icon:ShieldCheck},
 {key:'cards',label:'Report Cards',description:'Review student performance, remarks and printable report cards.',icon:Printer},
 {key:'reports',label:'Examination Reports',description:'Analyse class and subject outcomes, comparisons and progress.',icon:Activity},
]
const slug=(v:string)=>v.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')
const label=(v:any,alt='—')=>v===null||v===undefined||v===''?alt:String(v)
const sessionLabel=(s:Row)=>label(s.session_name??s.name??s.code)
const classLabel=(s:Row)=>[s.name??s.class_name,s.section].filter(Boolean).join(' / ')||label(s.grade_level)
const subjectLabel=(s:Row)=>label(s.name??s.subject_name??s.title)
const teacherLabel=(s:Row)=>label(s.full_name??s.name??s.employee_no)
const dateLabel=(v:any)=>v?new Date(String(v).slice(0,10)+'T00:00:00').toLocaleDateString():'—'
const localDateTimeToIso=(v:string)=>v?new Date(v).toISOString():null
const safeXml=(v:any)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')
const safeHtml=(v:any)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')
const download=(name:string,body:string,type:string)=>{const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
const csv=(v:any)=>'"'+String(v??'').replace(/"/g,'""')+'"'
const routeKey=(route:string):Key=>{const last=route.split(':').pop()||'';const aliases:Record<string,Key>={'examination-programs':'programs','examination-timetable':'timetable','question-bank':'questions','online-tests-and-quizzes':'online','marks-entry':'marks','grades-and-grading-system':'grading','results-and-result-approval':'results','report-cards':'cards','examination-reports':'reports'};if(aliases[last])return aliases[last];return tabs.find(t=>slug(t.label)===last)?.key??'programs'}

