 async function saveExam(event:FormEvent){event.preventDefault();if(!supabase||!user)return;const c=classes.find(x=>x.id===exam.class_id),s=subjects.find(x=>x.id===exam.subject_id),session=sessions.find(x=>x.id===exam.academic_session_id),max=Number(exam.total_marks),pass=Number(exam.pass_marks);if(!c||!s||!exam.title.trim()||max<=0||pass<0||pass>max||Number(exam.duration_minutes)<=0){onToast('Check the examination name, class, subject and marks limits.',true);return}setBusy(true);const values={institution_id:user.institutionId,title:exam.title.trim(),exam_type:exam.exam_type,academic_session:session?sessionLabel(session):null,academic_session_id:exam.academic_session_id||null,class_id:c.id,class_name:classLabel(c),subject_id:s.id,subject:subjectLabel(s),exam_date:exam.exam_date,start_time:exam.start_time||null,duration_minutes:Number(exam.duration_minutes),room:exam.room||null,invigilator:exam.invigilator||null,total_marks:max,pass_marks:pass,term:exam.term||null,instructions:exam.instructions||null,responsible_staff_id:exam.responsible_staff_id||null,program_code:slug(exam.title),status:editingExam?.status??'planned'};const q=editingExam?await supabase.from('exams').update(values).eq('id',editingExam.id).eq('institution_id',user.institutionId):await supabase.from('exams').insert({...values,created_by:user.id});setBusy(false);if(q.error){onToast(q.error.message,true);return}setExamOpen(false);onToast(editingExam?'Examination updated.':'Examination paper created.');await load()}
