 async function saveQuestion(event:FormEvent){event.preventDefault();if(!supabase||!user)return;const options=question.options.split('\n').map(v=>v.trim()).filter(Boolean),marks=Number(question.marks);if(!question.prompt.trim()||marks<=0||(question.question_type==='multiple_choice'&&options.length<2)){onToast('Add the question prompt, a positive mark value and at least two options for multiple-choice.',true);return}setBusy(true);const {error}=await supabase.from('question_bank_items').insert({institution_id:user.institutionId,question_code:'Q-'+Date.now().toString(36).toUpperCase(),question_type:question.question_type,prompt:question.prompt.trim(),options:question.question_type==='multiple_choice'?options:question.question_type==='true_false'?['True','False']:[],answer_key:question.answer_key,explanation:question.explanation||null,marks,subject_id:question.subject_id||null,class_id:question.class_id||null,topic:question.topic||null,difficulty:question.difficulty,status:canApprove?'published':'review',created_by:user.id});setBusy(false);if(error){onToast(error.message,true);return}setQuestionOpen(false);onToast(canApprove?'Question added to the published bank.':'Question sent for review.');await load()}
 async function qtiImport(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file||!supabase||!user)return;try{const doc=new DOMParser().parseFromString(await file.text(),'application/xml');if(doc.querySelector('parsererror'))throw new Error('The selected file is not valid XML.');const nodes=Array.from(doc.getElementsByTagNameNS('*','qti-assessment-item'));if(!nodes.length)throw new Error('No QTI assessment-item elements were found.');let count=0;for(const node of nodes){const prompt=node.getElementsByTagNameNS('*','qti-item-body')[0]?.textContent?.trim()||node.getAttribute('title')||'Imported item';const optionNodes=Array.from(node.getElementsByTagNameNS('*','qti-simple-choice'));const options=optionNodes.map(x=>x.textContent?.trim()||'').filter(Boolean);const key=node.getElementsByTagNameNS('*','qti-correct-response')[0]?.getElementsByTagNameNS('*','qti-value')[0]?.textContent?.trim()||'';const idx=optionNodes.findIndex(x=>x.getAttribute('identifier')===key);const answer=idx>=0?options[idx]??key:key;const result=await supabase.from('question_bank_items').insert({institution_id:user.institutionId,question_code:'QTI-'+Date.now().toString(36)+'-'+count,question_type:options.length?'multiple_choice':'long_answer',prompt,options,answer_key:answer,marks:1,difficulty:'medium',status:canApprove?'published':'review',created_by:user.id});if(result.error)throw result.error;count++}onToast(count+' QTI item(s) imported.');await load()}catch(e){onToast(e instanceof Error?e.message:'QTI import failed.',true)}finally{event.target.value=''}}
 function qtiExport(){const selected=questions.filter(q=>pickedQuestions.includes(q.id));if(!selected.length){onToast('Select one or more questions first.',true);return}const items=selected.map((q,i)=>{const opts=Array.isArray(q.options)?q.options:[];const choices=opts.map((v:any,j:number)=>'<qti-simple-choice identifier="CHOICE_'+(j+1)+'">'+safeXml(typeof v==='string'?v:v.label??v.text??'')+'</qti-simple-choice>').join('');const answer=String(q.answer_key??''),index=opts.findIndex((v:any)=>String(typeof v==='string'?v:v.label??v.text??'')===answer),key=index>=0?'CHOICE_'+(index+1):answer;return '<qti-assessment-item xmlns="http://www.imsglobal.org/xsd/imsqtiasi_v3p0" identifier="'+safeXml(q.question_code??('ITEM_'+i))+'" title="EduSphere question" adaptive="false" time-dependent="false"><qti-response-declaration identifier="RESPONSE" cardinality="single" base-type="identifier"><qti-correct-response><qti-value>'+safeXml(key)+'</qti-value></qti-correct-response></qti-response-declaration><qti-outcome-declaration identifier="SCORE" cardinality="single" base-type="float"><qti-default-value><qti-value>0</qti-value></qti-default-value></qti-outcome-declaration><qti-item-body><p>'+safeXml(q.prompt)+'</p>'+(opts.length?'<qti-choice-interaction response-identifier="RESPONSE" max-choices="1">'+choices+'</qti-choice-interaction>':'<qti-text-entry-interaction response-identifier="RESPONSE" expected-length="80"/>')+'</qti-item-body><qti-response-processing template="http://www.imsglobal.org/question/qti_v3p0/rptemplates/match_correct"/></qti-assessment-item>'});download('edusphere-qti-3-items.xml','<?xml version="1.0" encoding="UTF-8"?>\n<qti-item-bank xmlns="http://www.imsglobal.org/xsd/imsqtiasi_v3p0">'+items.join('\n')+'</qti-item-bank>','application/xml');onToast('QTI 3 item XML exported.')}
